import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlockTime) public {
        // Bound unlockTime to a reasonable range to keep the domain wide but relevant
        unlockTime = bound(unlockTime, 0, type(uint64).max);

        // Set up the actor with some Ether
        address actor = address(0x1);
        uint256 amount = 1 ether;
        vm.deal(actor, amount);

        // Record balance before Put
        uint256 balanceBefore = actor.balance;

        // Actor calls Put with Ether
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        // Calculate total Ether sent by this actor via Put
        // Since balance decreased by amount, the amount sent is balanceBefore - actor.balance
        uint256 totalSent = balanceBefore - actor.balance;

        // Invariant: The recorded balance in Acc for this actor must equal the total Ether sent via Put
        ( , uint256 recordedBalance) = c.Acc(actor);
        assertTrue(recordedBalance == totalSent);
    }
}

