pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address[] memory callers, uint256[] memory amounts, uint256[] memory unlockTimes) public {
        // Bound array lengths to keep the domain wide but manageable
        uint256 len = callers.length;
        vm.assume(len > 0 && len < 10);
        vm.assume(len == amounts.length);
        vm.assume(len == unlockTimes.length);

        // Track total ETH deposited via Put for each caller
        mapping(address => uint256) memory deposited;
        uint256 totalDeposited = 0;

        // Perform Put calls for each caller
        for (uint256 i = 0; i < len; i++) {
            address caller = callers[i];
            uint256 amt = amounts[i];
            vm.assume(amt > 0 && amt < type(uint128).max); // avoid overflow in deposited tracking
            vm.assume(caller != address(0) && caller != address(this) && caller != address(c));
            vm.deal(caller, amt);
            vm.prank(caller);
            c.Put{value: amt}(unlockTimes[i]);
            deposited[caller] += amt;
            totalDeposited += amt;
        }

        // Now simulate Collect calls for those whose unlockTime has passed and balance >= MinSum
        // Collect reduces contract ETH but also reduces Acc balance, conservation should hold
        vm.warp(block.timestamp + 1 days); // move past all unlock times
        uint256 totalCollected = 0;
        for (uint256 i = 0; i < len; i++) {
            address caller = callers[i];
            uint256 balance = c.Acc(caller).balance;
            uint256 unlockTime = c.Acc(caller).unlockTime;
            if (balance >= c.MinSum() && block.timestamp > unlockTime) {
                uint256 collectAmt = balance;
                vm.prank(caller);
                try c.Collect(collectAmt) {
                    totalCollected += collectAmt;
                } catch { }
            }
        }

        // Compute sum of current Acc balances
        uint256 sumBalances = 0;
        for (uint256 i = 0; i < len; i++) {
            sumBalances += c.Acc(callers[i]).balance;
        }

        // Conservation: sumBalances + totalCollected == address(c).balance + totalCollected ? no
        // Correct: sum of balances + total collected should equal total deposited
        // but collected amounts come from c, so address(c).balance = totalDeposited - totalCollected
        // and each Acc balance = deposited[caller] - collected_by_caller
        // thus sumBalances + totalCollected = totalDeposited
        // Therefore address(c).balance = sumBalances
        // Invariant: address(c).balance + totalCollected == totalDeposited
        // Simpler: sumBalances == address(c).balance
        assertTrue(sumBalances == address(c).balance);
    }
}

