pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount, uint256 unlockTime, uint256 collectAmt) public {
        // Domain: amount must be at least 1 ether to allow future Collect, and collectAmt must be <= amount
        vm.assume(amount >= 1 ether);
        vm.assume(collectAmt <= amount);
        // Unlock time must be in the past to allow Collect after setup
        vm.warp(1000);
        vm.assume(unlockTime < 1000);

        address alice = address(0x1);
        vm.deal(alice, amount);
        vm.prank(alice);
        c.Put{value: amount}(unlockTime);

        uint256 balanceBefore = c.Acc(alice).balance;
        // Skip time past unlock to allow Collect
        vm.warp(2000);
        bool ok;
        try c.Collect(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }
        if (ok) {
            uint256 balanceAfter = c.Acc(alice).balance;
            assertTrue(balanceAfter < balanceBefore);
        }
        // If Collect fails, the property vacuously holds; the rule is conditioned on a successful Collect.
        // With the reference, a successful Collect reduces balance; the buggy version never updates balance on Put,
        // so a successful Collect (only possible with a pre-existing balance) will violate the strict inequality
        // if the fuzzer supplies a non-zero amount that the buggy version fails to add, leading to no balance reduction.
    }
}

