contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlockTime, uint256 putAmount, uint256 collectAmount) public {
        // Admissible domain: putAmount > 0 and collectAmount > 0, avoid overflow in Put's require
        vm.assume(putAmount > 0);
        vm.assume(collectAmount > 0);
        vm.assume(putAmount <= type(uint256).max - putAmount);
        // Ensure unlockTime is in the past so that block.timestamp > unlockTime condition is met
        bound(unlockTime, 0, block.timestamp - 1);

        address actor = address(0x1234);
        vm.deal(actor, putAmount);

        // Actor calls Put with some msg.value
        vm.prank(actor);
        c.Put{value: putAmount}(unlockTime);

        // Warp past the unlock time to satisfy Collect's block.timestamp > acc.unlockTime condition
        vm.warp(block.timestamp + 1);

        // Collect must succeed for collectAmount <= putAmount (which must be true since balance is at least putAmount)
        // The buggy version never increments balance, so Collect will revert
        bool ok;
        vm.prank(actor);
        try c.Collect(collectAmount) { ok = true; } catch { ok = false; }

        // The reference C holds: if collectAmount <= putAmount and unlockTime condition is met, Collect succeeds.
        // The buggy M breaks it: Collect always reverts because balance is 0.
        assertTrue(ok);
    }
}

