import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 preBalance, uint256 sendValue, uint256 unlockTime) public {
        // keep preBalance non-zero so overflow can change the relative magnitude vs sendValue
        bound(preBalance, 1, type(uint256).max);
        // sendValue must be less than preBalance so pre-balance remains > 0 after overflow wrap
        bound(sendValue, 1, preBalance);
        vm.deal(address(this), sendValue);
        // warp past unlock time so unlockTime constraint does not interfere
