        vm.deal(address(this), preBalance);
        c.Put{value: preBalance}(unlockTime);
        // now call Put with the fuzzed sendValue
        vm.deal(address(this), sendValue);
        c.Put{value: sendValue}(unlockTime);
        // the sender's balance after the second Put must be strictly greater than the sendValue
        // (since preBalance was non-zero)
        (, uint256 finalBal) = c.Acc(address(this));
        assertTrue(finalBal > sendValue);
    }
